// ============================================
// VALIDATION INPUT - MCP Tools Enricher
// ============================================

const input = $input.first().json;
const body = input.body || input;
const headers = input.headers || {};

// Support RFC-014: data in context.* with fallback to root level
const ctx = body.context || {};

const errors = [];

// --- API keys from headers, body, or env ---
const anthropicKey = body.api_keys?.anthropic || ctx.api_keys?.anthropic || $env.ANTHROPIC_API_KEY;
const openaiKey = body.api_keys?.openai || ctx.api_keys?.openai || $env.OPENAI_API_KEY;
const n8nApiKey = headers['x-n8n-api-key'] || headers['X-N8N-API-KEY'] || body.n8n_api_key || ctx.n8n_api_key || $env.N8N_API_KEY;

// Get models from env
const modelAnthropic = $env.MODEL_ANTHROPIC || 'claude-3-5-haiku-20241022';
const modelOpenai = $env.MODEL_OPENAI || 'gpt-4o-mini';

// Qdrant config - use shared instance
const qdrantHost = body.qdrant_host || ctx.qdrant_host || $env.QDRANT_SHARED_1_HOST || 'host3.local';
const qdrantPort = body.qdrant_port || ctx.qdrant_port || $env.QDRANT_SHARED_1_PORT || '20001';
const qdrantApiKey = body.qdrant_api_key || ctx.qdrant_api_key || $env.QDRANT_SHARED_1_API_KEY || '';
const qdrantCollection = body.qdrant_collection || ctx.qdrant_collection || 'tools_index';

// Options
const mode = body.mode || ctx.mode || 'full';
const workflowIds = body.workflow_ids || ctx.workflow_ids || [];
const dryRun = body.dry_run === true || ctx.dry_run === true;
const batchSize = body.batch_size || ctx.batch_size || 10;

// Async callback pattern (RFC-040)
const callbackUrl = body.callback_url || ctx.callback_url || null;
// Generate UUID without crypto (n8n doesn't support Node.js crypto module)
const generateUUID = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
  const r = Math.random() * 16 | 0;
  return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
});
const jobId = body.job_id || ctx.job_id || generateUUID();

// Validate API keys only after required fields
if (!anthropicKey) errors.push('Missing ANTHROPIC_API_KEY');
if (!openaiKey) errors.push('Missing OPENAI_API_KEY');
if (!n8nApiKey) errors.push('Missing N8N_API_KEY');

const now = new Date();

if (errors.length > 0) {
  return [{
    json: {
      valid: false,
      errors: errors,
      callbackUrl: callbackUrl,
      jobId: jobId
    }
  }];
}

// Initialize static data for results tracking
const staticData = $getWorkflowStaticData('global');
staticData.results = [];
staticData.jobId = jobId;
staticData.startedAt = now.toISOString();
staticData.callbackUrl = callbackUrl;

return [{
  json: {
    valid: true,
    config: {
      jobId,
      callbackUrl,
      anthropicKey,
      openaiKey,
      n8nApiKey,
      modelAnthropic,
      modelOpenai,
      qdrantUrl: `http://${qdrantHost}:${qdrantPort}`,
      qdrantApiKey,
      qdrantCollection,
      mode,
      workflowIds,
      dryRun,
      batchSize
    },
    stats: {
      startedAt: now.toISOString()
    },
    startTime: Date.now()
  }
}];

const n8nData = $('Get Workflows').first().json;
const qdrantData = $input.first().json;
const config = $('Validate Input').first().json.config;

if (n8nData.error) {
  return [];
}

// Get already indexed workflow_ids with their metadata
const indexedMap = new Map();
if (qdrantData.result?.points) {
  for (const p of qdrantData.result.points) {
    indexedMap.set(p.payload.workflow_id, {
      source_updated_at: p.payload.source_updated_at,
      keywords: p.payload.keywords || [],
      operations: p.payload.operations || [],
      use_cases: p.payload.use_cases || []
    });
  }
}
console.log(`[Enricher] Found ${indexedMap.size} already indexed workflows`);

// Helper: check if metadata is empty/incomplete
function hasEmptyMetadata(indexed) {
  if (!indexed) return true;
  const noKeywords = !indexed.keywords || indexed.keywords.length === 0;
  const noOperations = !indexed.operations || indexed.operations.length === 0;
  const noUseCases = !indexed.use_cases || indexed.use_cases.length === 0;
  return noKeywords || noOperations || noUseCases;
}

const allWorkflows = n8nData.data || [];

// Filter: has webhook, not Registry/System workflows
let workflows = allWorkflows.filter(w => {
  if (!w.active) return false;
  if (w.name.includes('Registry')) return false;
  if (w.name.includes('Enricher')) return false;
  const hasWebhook = w.nodes?.some(n => n.type === 'n8n-nodes-base.webhook');
  return hasWebhook;
});

// Mode: specific - force update specified IDs
if (config.mode === 'specific' && config.workflowIds.length > 0) {
  workflows = workflows.filter(w => config.workflowIds.includes(w.id));
  console.log(`[Enricher] Specific: ${workflows.length} workflows to process`);
}

// Mode: incremental - exclude already indexed (unless updated OR metadata empty)
if (config.mode === 'incremental') {
  workflows = workflows.filter(w => {
    const indexed = indexedMap.get(w.id);
    if (!indexed) return true; // Not indexed yet
    // Re-index if metadata is empty
    if (hasEmptyMetadata(indexed)) {
      console.log(`[Enricher] Re-indexing ${w.name}: empty metadata`);
      return true;
    }
    // Re-index if workflow was updated after last indexing
    return new Date(w.updatedAt) > new Date(indexed.source_updated_at);
  });
  console.log(`[Enricher] Incremental: ${workflows.length} new/updated/empty workflows to process`);
}

// Return items for SplitInBatches
return workflows.map(w => {
  const webhookNode = w.nodes?.find(n => n.type === 'n8n-nodes-base.webhook');
  const stickyNote = w.nodes?.find(n => n.type === 'n8n-nodes-base.stickyNote');
  const codeNodes = w.nodes?.filter(n => n.type === 'n8n-nodes-base.code') || [];
  const httpNodes = w.nodes?.filter(n => n.type === 'n8n-nodes-base.httpRequest') || [];
  const nodeTypes = [...new Set(w.nodes?.map(n => n.type.replace('n8n-nodes-base.', '')) || [])];
  const codeSnippets = codeNodes.slice(0, 3).map(n => (n.parameters?.jsCode || '').substring(0, 500));
  const httpUrls = httpNodes.map(n => n.parameters?.url || '').filter(u => u);

  console.log(`[Enricher] Queued: ${w.name}`);

  return {
    json: {
      workflow_id: w.id,
      name: w.name,
      webhook_path: webhookNode?.parameters?.path || webhookNode?.webhookId || '',
      webhook_method: webhookNode?.parameters?.httpMethod || 'POST',
      sticky_content: stickyNote?.parameters?.content || '',
      node_types: nodeTypes,
      node_count: w.nodes?.length || 0,
      code_snippets: codeSnippets,
      http_urls: httpUrls,
      updated_at: w.updatedAt,
      config
    }
  };
});

const workflow = $input.first().json;
const config = workflow.config;
const validateData = $('Validate Input').first().json;
const userRequest = validateData.user_request || '';

// Sanitize text for JSON (remove problematic chars)
function sanitize(text, maxLen = 500) {
  if (!text) return '';
  return String(text)
    .substring(0, maxLen)
    .replace(/[\x00-\x1F\x7F]/g, ' ')
    .replace(/\\/g, '\\\\')
    .replace(/"/g, '\\"')
    .trim();
}

// Build context
const context = {
  name: workflow.name,
  webhook_path: workflow.webhook_path,
  webhook_method: workflow.webhook_method,
  node_types: workflow.node_types.join(', '),
  node_count: workflow.node_count,
  existing_doc: sanitize(workflow.sticky_content, 400),
  code_samples: sanitize(workflow.code_snippets.join(' --- '), 600),
  http_endpoints: workflow.http_urls.join(', ')
};

// Build Claude request body with user_request context
const claudeBody = {
  model: config.modelAnthropic,
  max_tokens: 2000,
  tools: [{
    name: 'enrich_tool_metadata',
    description: 'Generate structured metadata for an n8n workflow tool',
    input_schema: {
      type: 'object',
      required: ['description', 'category', 'keywords', 'use_cases', 'operations'],
      properties: {
        description: { type: 'string', description: 'Concise description (max 100 chars), verb infinitive' },
        category: { type: 'string', enum: ['recherche', 'traduction', 'media', 'documents', 'email', 'calendar', 'database', 'ai', 'communication', 'finance', 'torah', 'autre'] },
        keywords: { type: 'array', items: { type: 'string' }, description: '5-15 keywords FR and EN' },
        use_cases: { type: 'array', items: { type: 'string' }, description: '2-5 concrete examples' },
        operations: {
          type: 'array',
          items: {
            type: 'object',
            required: ['id', 'type', 'verbs_fr', 'verbs_en'],
            properties: {
              id: { type: 'string' },
              type: { type: 'string', enum: ['READ', 'WRITE'] },
              verbs_fr: { type: 'array', items: { type: 'string' } },
              verbs_en: { type: 'array', items: { type: 'string' } }
            }
          },
          description: 'Operations with READ/WRITE type and associated verbs'
        }
      }
    }
  }],
  tool_choice: { type: 'tool', name: 'enrich_tool_metadata' },
  messages: [{
    role: 'user',
    content: `**Demande utilisateur:** ${userRequest}

Analyse ce workflow n8n et genere des metadonnees structurees.

WORKFLOW:
- Nom: ${context.name}
- Webhook: ${context.webhook_method} /${context.webhook_path}
- Nodes (${context.node_count}): ${context.node_types}
- Documentation: ${context.existing_doc}
- Code: ${context.code_samples}
- HTTP endpoints: ${context.http_endpoints}

REGLES:
- description: max 100 chars, verbe infinitif
- keywords: FR et EN, synonymes inclus
- use_cases: commencer par un verbe
- operations: identifier TOUTES les actions (READ=consulter/lire, WRITE=creer/envoyer/modifier)

Utilise l'outil enrich_tool_metadata.`
  }]
};

return [{
  json: {
    ...workflow,
    context,
    claudeBody,
    user_id: validateData.user_id,
    guild_id: validateData.guild_id,
    user_request: userRequest
  }
}];

const input = $input.first().json;
const prevData = $('Process Workflow').first().json;

if (input.error) {
  return [{
    json: {
      ...prevData,
      claude_result: null,
      claude_error: input.error.message || 'Claude API error',
      status: 'claude_failed'
    }
  }];
}

try {
  // Extract tool use result
  const toolUse = input.content?.find(c => c.type === 'tool_use');
  if (!toolUse || !toolUse.input) {
    return [{
      json: {
        ...prevData,
        claude_result: null,
        claude_error: 'No tool_use in response',
        status: 'claude_failed'
      }
    }];
  }

  return [{
    json: {
      ...prevData,
      claude_result: toolUse.input,
      claude_usage: input.usage || {},
      status: 'claude_ok'
    }
  }];
} catch (e) {
  return [{
    json: {
      ...prevData,
      claude_result: null,
      claude_error: 'Parse error: ' + e.message,
      status: 'claude_failed'
    }
  }];
}

