  return [{
    json: {
      ...prevData,
      claude_result: toolUse.input,
      claude_usage: input.usage || {},
      status: 'claude_ok'
    }
  }];
} catch (e) {
  return [{
    json: {
      ...prevData,
      claude_result: null,
      claude_error: 'Parse error: ' + e.message,
      status: 'claude_failed'
    }
  }];
}

