const config = $('Validate Input').first().json.config;
const validateData = $('Validate Input').first().json;
const staticData = $getWorkflowStaticData('global');
const results = staticData.results || [];
const startedAt = staticData.startedAt;

// Context fields
const userId = staticData.userId || validateData.user_id;
const guildId = staticData.guildId || validateData.guild_id;
const userRequest = staticData.userRequest || validateData.user_request;

// Calculate stats
const enriched = results.filter(r => r.status === 'enriched').length;
const dryRunCount = results.filter(r => r.status === 'dry_run').length;
const failed = results.filter(r => r.status === 'failed' || r.status === 'qdrant_failed').length;
const errorList = results.filter(r => r.status === 'failed' || r.status === 'qdrant_failed');

const latencyMs = Date.now() - new Date(startedAt).getTime();

const stats = {
  job_id: staticData.jobId,
  mode: config.mode,
  dry_run: config.dryRun,
  total: results.length,
  enriched,
  dry_run_count: dryRunCount,
  failed,
  duration_ms: latencyMs,
  collection: config.qdrantCollection
};

// Build _trace for Langfuse
const _trace = {
  service_response: stats,
  provider: 'anthropic+openai',
  mode: config.mode,
  latency_ms: latencyMs,
  user_id: userId,
  guild_id: guildId,
  user_request: userRequest
};

const responseBody = {
  success: failed === 0,
  job_id: staticData.jobId,
  status: 'completed',
  message: failed === 0
    ? `Enrichment completed: ${enriched} tools indexed.`
    : `Enrichment completed with ${failed} errors.`,
  stats,
  errors: errorList.length > 0 ? errorList : null,
  results: results,
  _trace: _trace,
  user_id: userId,
  guild_id: guildId,
  user_request: userRequest
};

return [{
  json: {
    responseBody,
    callbackUrl: staticData.callbackUrl
  }
}];

const crypto = require('crypto');
const input = $input.first().json;

const callbackUrl = input.callbackUrl;
const body = input.responseBody;
const payload = JSON.stringify(body);

// RFC-040: HMAC signature - sign body only, output hex WITHOUT prefix
const secret = $env.N8N_WEBHOOK_SECRET || 'default-secret';
const signature = crypto.createHmac('sha256', secret).update(payload).digest('hex');

console.log(`[Enricher] Sending callback to ${callbackUrl}`);

return [{
  json: {
    callbackUrl,
    payload,
    signature
  }
}];

const input = $input.first().json;
